import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('useMemo & useCallback', () => {
  test('Shows all 7 items by default', async () => {
    const { container: root } = render(<App />);
    const items = root.querySelectorAll('#results li');
if (items.length !== 7) throw new Error('Expected 7 items initially, got ' + items.length);
  });

  test('Typing "a" narrows to items containing "a"', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#filter');
if (!input) throw new Error('No input with id "filter" found');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'a');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
const items = root.querySelectorAll('#results li');
const texts = Array.from(items).map(li => li.textContent);
const expected = ['apple', 'banana', 'date', 'grape'];
if (items.length !== expected.length)
  throw new Error('Expected ' + expected.length + ' items containing "a", got ' + items.length);
for (const want of expected) {
  if (!texts.includes(want)) throw new Error('Missing item "' + want + '" in filtered list');
}
  });

  test('A no-match query renders zero items', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#filter');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'zzz');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
const items = root.querySelectorAll('#results li');
if (items.length !== 0) throw new Error('Expected 0 items for "zzz", got ' + items.length);
  });

  test('Filter is case-insensitive', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#filter');
const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
setter.call(input, 'BAN');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
const items = root.querySelectorAll('#results li');
const texts = Array.from(items).map(li => li.textContent);
if (!texts.includes('banana'))
  throw new Error('Expected "banana" to match query "BAN" (case-insensitive)');
  });
});
